member.example:
Example of Printing called from workflow.

             PrintSystem.Reset();

             //Used for Print XRef lookups
             PrintSystem.Branch = "Branch";
             PrintSystem.ItemNumber = "Item#;
             PrintSystem.Location = "LO.CN";

             //If not using Default Printer validate printer name
             string PrinterName = "PrinterA";
             //Check and make sure DefaultPrinter exists and that Printer Name is valid.
             if (PrintSystem.DefaultPrinter.Length == 0 ||
               !PrintSystem.ValidPrinter(PrinterName))
             {
               //Do some error handling
             }
             else
             {
               PrintSystem.DropFilePathOverride = "C:\LabelDrop\";
               PrintSystem.PrinterAddress = PrintSystem.PrinterAddress;;
               PrintSystem.PrinterName = PrinterName;
               PrintSystem.Copies = 2;

               //If looking to add additional data to drop file
               //Use ExtraPrintData
               PrintSystem.ExtraPrintData.AddColumnAndSetDefaultData("Field1", "123", false);
               PrintSystem.ExtraPrintData.AddColumnAndSetDefaultData("Field2", "456", false);
               PrintSystem.ExtraPrintData.AddColumnAndSetDefaultData("Field3", "789", false);
               //NewRow must be called to insert additional data rows.
               PrintSystem.ExtraPrintData.NewRow();

               //If print fails Display message to user on next screen.
                if (!PrintSystem.Print())
               {
                  DisplayMessage(PrintSystem.ErrorMessageVocabulary);
               }
             }
